() => {
  const fs = require('fs');
  const { execSync } = require('child_process');

  try {
    // Make script executable
    execSync('chmod +x /tmp/cleanup_playwright.sh');

    // Run the script
    const result = execSync('/tmp/cleanup_playwright.sh', { encoding: 'utf-8' });
    return result;
  } catch (error) {
    return `Error: ${error.message}`;
  }
}

() => {
  const { execSync } = require('child_process');

  try {
    // Count how many playwright artifacts directories exist
    const countResult = execSync('ls -d /tmp/playwright-artifacts-* 2>/dev/null | wc -l', { encoding: 'utf-8' });
    const count = parseInt(countResult.trim());

    // Remove playwright artifacts directories
    execSync('rm -rf /tmp/playwright-artifacts-*', { stdio: 'pipe' });

    // Remove playwright chromium dev profile directories
    execSync('rm -rf /tmp/playwright_chromiumdev_profile-*', { stdio: 'pipe' });

    return `Successfully removed approximately ${count} Playwright temporary directories and all Playwright chromium dev profile directories.`;
  } catch (error) {
    return `Error: ${error.message}`;
  }
}

